// static
bool StructTraits<::ash::libassistant::mojom::BootupConfig::DataView, ::ash::libassistant::mojom::BootupConfigPtr>::Read(
    ::ash::libassistant::mojom::BootupConfig::DataView input,
    ::ash::libassistant::mojom::BootupConfigPtr* output) {
  bool success = true;
  ::ash::libassistant::mojom::BootupConfigPtr result(::ash::libassistant::mojom::BootupConfig::New());
  
      if (success && !input.ReadS3ServerUriOverride(&result->s3_server_uri_override))
        success = false;
      if (success && !input.ReadDeviceIdOverride(&result->device_id_override))
        success = false;
      if (success && !input.ReadAuthenticationTokens(&result->authentication_tokens))
        success = false;
      if (success && !input.ReadLocale(&result->locale))
        success = false;
      if (success)
        result->spoken_feedback_enabled = input.spoken_feedback_enabled();
      if (success)
        result->dark_mode_enabled = input.dark_mode_enabled();
      if (success)
        result->hotword_enabled = input.hotword_enabled();
  *output = std::move(result);
  return success;
}

